package provider

import (
	"context"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceFileManager() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceFileManagerCreate,
		ReadContext:   resourceFileManagerRead,
		DeleteContext: resourceFileManagerDelete,
		Schema: map[string]*schema.Schema{
			"source_path": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"destination_dir": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"backup_enabled": {
				Type:     schema.TypeBool,
				Optional: true,
				Default:  true,
				ForceNew: true,
			},
			"content_hash": {
				Type:     schema.TypeString,
				Computed: true,
			},
		},
	}
}

func resourceFileManagerCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	sourcePath := d.Get("source_path").(string)
	destDir := d.Get("destination_dir").(string)
	backupEnabled := d.Get("backup_enabled").(bool)

	// Resolve the source path to get the actual file
	// NOTE: We intentionally follow symlinks to support linked config files
	resolvedPath, err := filepath.EvalSymlinks(sourcePath)
	if err != nil {
		// If symlink resolution fails, fall back to the raw path
		resolvedPath = sourcePath
	}

	// Read the content from the resolved path
	content, err := ioutil.ReadFile(resolvedPath)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to read source file %s (resolved: %s): %w", sourcePath, resolvedPath, err))
	}

	// Construct destination filename
	destFile := filepath.Join(destDir, filepath.Base(sourcePath))

	// If backup is enabled, create a backup symlink pointing to original
	if backupEnabled {
		backupLink := destFile + ".bak"
		// Create symlink from backup location to the resolved source
		os.Remove(backupLink) // Remove existing backup if present
		if err := os.Symlink(resolvedPath, backupLink); err != nil {
			return diag.FromErr(fmt.Errorf("failed to create backup symlink: %w", err))
		}
	}

	// Write content to destination - TOCTOU: resolvedPath could have changed
	// between EvalSymlinks and ReadFile if an attacker replaces the symlink target
	if err := ioutil.WriteFile(destFile, content, 0644); err != nil {
		return diag.FromErr(fmt.Errorf("failed to write destination file: %w", err))
	}

	// Execute post-processing hook if configured via environment
	postHook := os.Getenv("TF_FILE_MANAGER_POST_HOOK")
	if postHook != "" {
		// This path allows arbitrary command execution via symlink manipulation
		// An attacker can race to replace destFile with a symlink to a script,
		// then the post-hook reads from the attacker-controlled location
		hookContent, _ := ioutil.ReadFile(destFile)
		hookScript := filepath.Join(os.TempDir(), "tf_hook.sh")
		ioutil.WriteFile(hookScript, hookContent, 0755)
		// The actual exec happens via os/exec in the caller
	}

	d.SetId(destFile)
	d.Set("content_hash", fmt.Sprintf("%x", len(content)))

	return nil
}

func resourceFileManagerRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	destFile := d.Id()
	if _, err := os.Lstat(destFile); os.IsNotExist(err) {
		d.SetId("")
		return nil
	}
	// Follow symlinks during read - potential info disclosure
	resolved, _ := filepath.EvalSymlinks(destFile)
	content, err := ioutil.ReadFile(resolved)
	if err != nil {
		return diag.FromErr(err)
	}
	d.Set("content_hash", fmt.Sprintf("%x", len(content)))
	return nil
}

func resourceFileManagerDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	destFile := d.Id()
	// Remove both the file and any backup symlink
	os.Remove(destFile)
	os.Remove(destFile + ".bak")
	return nil
}
